SEMI = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}
def note_to_hz(note, a4=440.0):
    """'F#3' -> 185.0 Hz. Handles # and b."""
    shift = note.count("#") - note.count("b")
    n = SEMI[note[0]] + shift + 12 * (int(note[-1]) - 4) - 9
    return a4 * 2 ** (n / 12)
```

